function rrfFuse(lists, k = 60, topN = Infinity) {
  const scores = new Map() // docId -> rrf score
  for (const list of lists) {
    for (let rank = 0; rank < list.length; rank++) {
      const id = list[rank]
      const add = 1 / (k + rank + 1) // 名次第1位 => 1/(k+1)
      scores.set(id, (scores.get(id) ?? 0) + add)
    }
  }
  return [...scores.entries()]
    .sort((a, b) =>
      b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0)) // 并列按 id 稳定
    .slice(0, topN)
    .map(([id]) => id)
}
// 例：rrfFuse([['d3','d1','d2'], ['d2','d3','d9']], 60)
// d3: 1/61 + 1/62, d2: 1/63 + 1/61, d1: 1/62, d9: 1/63
// => ['d3', 'd2', 'd1', 'd9']

function chunk(doc) {
  const cutSentences = (t, size = 1200, over = 100) => {
    if (t.length <= size) return [t]
    const out = []; let start = 0
    while (start < t.length) {
      let end = Math.min(start + size, t.length)
      if (end < t.length) { // 退回最近的句子边界
        const m = t.slice(start, end).match(/[^。！？.]*[。！？.](?=[^。！？.]*$)/)
        if (m && m.index > size * 0.5) end = start + m.index + m[0].length
      }
      out.push(t.slice(start, end).trim())
      if (end >= t.length) break
      start = Math.max(end - over, start + 1) // overlap 但保证前进
    }
    return out.filter(Boolean)
  }
  switch (doc.type) {
    case 'markdown': {
      const heads = [...doc.text.matchAll(/^#{2,} .*$/gm)]
      const bounds = [0, ...heads.map(m => m.index), doc.text.length]
      const blocks = []
      for (let i = 0; i < bounds.length - 1; i++) {
        const sec = doc.text.slice(bounds[i], bounds[i + 1])
        const head = heads[i - 1]?.[0] ?? ''
        for (const piece of cutSentences(sec))
          blocks.push({ text: piece, meta: { type: 'md', section: head.trim() } })
      }
      return blocks
    }
    case 'html': {
      const page = doc.text.match(/data-page="?(\d+)"?/)?.[1] ?? null
      const text = doc.text.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, '')
        .replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim()
      return cutSentences(text).map(t => ({ text: t, meta: { type: 'html', page } }))
    }
    case 'faq':
      return doc.text.map((qa, i) => ({ text: `Q: ${qa.q}\nA: ${qa.a}`, meta: { type: 'faq', id: i } }))
  }
}
